package com.bank.cachedecide.model;

// How a dataset is used: cost, reuse count, and size.
public class DatasetUsage {
    private final String name;
    private final int computeCostUnits; // relative expense to produce
    private final int reuseCount;        // number of actions reading it
    private final long sizeBytes;

    public DatasetUsage(String name, int computeCostUnits, int reuseCount, long sizeBytes) {
        this.name = name;
        this.computeCostUnits = computeCostUnits;
        this.reuseCount = reuseCount;
        this.sizeBytes = sizeBytes;
    }
    public String getName() { return name; }
    public int getComputeCostUnits() { return computeCostUnits; }
    public int getReuseCount() { return reuseCount; }
    public long getSizeBytes() { return sizeBytes; }
}
