package com.bank.cachedecide.advisor;

import java.util.logging.Logger;

// Tracks cache memory and simulates eviction under over-caching.
public class MemoryBudget {
    private static final Logger log = Logger.getLogger(MemoryBudget.class.getName());
    private final long capacityBytes;
    private long usedBytes = 0;

    public MemoryBudget(long capacityBytes) { this.capacityBytes = capacityBytes; }

    public boolean admit(String name, long sizeBytes) {
        if (usedBytes + sizeBytes <= capacityBytes) {
            usedBytes += sizeBytes;
            return true;
        }
        log.warning(() -> "EVICTION: caching '" + name + "' (" + sizeBytes
                + "B) exceeds budget — evicts useful cached data, may recompute");
        return false;
    }
    public long getUsedBytes() { return usedBytes; }
}
