package com.bank.cachedecide.advisor;

import com.bank.cachedecide.model.DatasetUsage;
import java.util.logging.Logger;

// Decides whether to cache a dataset and explains why.
public class CacheAdvisor {
    private static final Logger log = Logger.getLogger(CacheAdvisor.class.getName());
    private final MemoryBudget budget;

    public CacheAdvisor(MemoryBudget budget) { this.budget = budget; }

    public boolean shouldCache(DatasetUsage d) {
        // Rule: cache only if reused more than once AND expensive to compute.
        if (d.getReuseCount() <= 1) {
            log.info(() -> "SKIP '" + d.getName() + "': used once → no reuse benefit");
            return false;
        }
        if (d.getComputeCostUnits() <= 2) {
            log.info(() -> "SKIP '" + d.getName()
                    + "': tiny/cheap to recompute → caching wastes memory");
            return false;
        }
        // Good candidate — but respect the memory budget (avoid over-caching).
        if (!budget.admit(d.getName(), d.getSizeBytes())) {
            log.info(() -> "SKIP '" + d.getName() + "': over budget → do NOT cache here");
            return false;
        }
        log.info(() -> "CACHE '" + d.getName() + "': expensive (cost="
                + d.getComputeCostUnits() + ") AND reused " + d.getReuseCount() + "x");
        return true;
    }
}
