package com.bank.cachedecide;

import com.bank.cachedecide.advisor.*;
import com.bank.cachedecide.model.DatasetUsage;
import java.util.List;
import java.util.logging.*;

public class CacheDecisionDemo {
    private static final Logger log = Logger.getLogger(CacheDecisionDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new CacheDecLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        MemoryBudget budget = new MemoryBudget(100_000_000L); // 100 MB cache budget
        CacheAdvisor advisor = new CacheAdvisor(budget);

        List<DatasetUsage> datasets = List.of(
            // expensive + reused by 5 reports → CACHE
            new DatasetUsage("cleaned_txns", 9, 5, 40_000_000),
            // one-time extract written once → SKIP
            new DatasetUsage("daily_extract", 8, 1, 30_000_000),
            // tiny cheap lookup → SKIP
            new DatasetUsage("account_type_lookup", 1, 4, 1_000_000),
            // expensive feature matrix reused in ML loop → CACHE (if it fits)
            new DatasetUsage("ml_features", 10, 20, 50_000_000),
            // another expensive reused dataset but no budget left → SKIP (eviction)
            new DatasetUsage("branch_rollup", 7, 3, 40_000_000)
        );

        for (DatasetUsage d : datasets) advisor.shouldCache(d);
        log.info(() -> "cache memory used = " + budget.getUsedBytes() + "B of 100000000B");
    }
}

